// Compares the live sitemap URL list against the pages generated by the clone.
// Usage: node scripts/check-coverage.mjs
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, "..");
const SITEMAP_DIR = "/tmp/ikea-sitemaps";

function readSitemapUrls() {
  const urls = new Set();
  if (!fs.existsSync(SITEMAP_DIR)) return urls;
  for (const f of fs.readdirSync(SITEMAP_DIR)) {
    if (!f.endsWith(".xml")) continue;
    const xml = fs.readFileSync(path.join(SITEMAP_DIR, f), "utf8");
    for (const m of xml.matchAll(/<loc>([^<]+)<\/loc>/g)) {
      const u = m[1].replace("https://www.ikea.cn", "").replace(/\/$/, "");
      if (u) urls.add(u);
    }
  }
  return urls;
}

function family(url) {
  const parts = url.split("/").filter(Boolean);
  return parts[2] ?? "root";
}

const sitemap = readSitemapUrls();

// Clone coverage from the data layer
const covered = new Set();
// content pages
const pagesDir = path.join(repoRoot, "src", "data", "pages");
for (const f of fs.readdirSync(pagesDir)) {
  const pages = JSON.parse(fs.readFileSync(path.join(pagesDir, f), "utf8"));
  for (const p of pages) covered.add(p.url.replace(/\/$/, ""));
}
// catalog pages (crawled cat pages)
const catAll = JSON.parse(
  fs.readFileSync(path.join(repoRoot, "src", "data", "catalog-pages", "all.json"), "utf8"),
);
for (const p of catAll) covered.add(p.url.replace(/\/$/, ""));
// products in catalog.ts (sample PDPs) — slug -> /cn/zh/p/<slug>
const catalogSrc = fs.readFileSync(path.join(repoRoot, "src", "data", "catalog.ts"), "utf8");
for (const m of catalogSrc.matchAll(/"slug": "([^"]+)"/g)) {
  covered.add(`/cn/zh/p/${m[1]}`);
}
// full product dataset (if present)
const productsDir = path.join(repoRoot, "src", "data", "products");
if (fs.existsSync(productsDir)) {
  for (const f of fs.readdirSync(productsDir)) {
    if (!f.endsWith(".json")) continue;
    const products = JSON.parse(fs.readFileSync(path.join(productsDir, f), "utf8"));
    for (const p of products) if (p.slug) covered.add(`/cn/zh/p/${p.slug}`);
  }
}

const special = new Set(["/cn/zh", "/cn/zh/all-products"]);

const missing = [];
for (const url of sitemap) {
  if (covered.has(url) || special.has(url)) continue;
  // sub-category URLs: catalog.ts subs
  const subMatch = catalogSrc.match(new RegExp(`url: "https://www\\.ikea\\.cn${url.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}"`));
  if (subMatch) continue;
  missing.push(url);
}

const byFamily = new Map();
for (const url of missing) {
  const fam = family(url);
  if (!byFamily.has(fam)) byFamily.set(fam, []);
  byFamily.get(fam).push(url);
}

const byFamSitemap = new Map();
for (const url of sitemap) {
  const fam = family(url);
  byFamSitemap.set(fam, (byFamSitemap.get(fam) ?? 0) + 1);
}

console.log("=== sitemap totals ===");
console.log("sitemap unique URLs:", sitemap.size);
console.log("clone covered (data):", covered.size + special.size);
console.log("");
console.log("=== missing by family ===");
const rows = [...byFamily.entries()].sort((a, b) => b[1].length - a[1].length);
let total = 0;
for (const [fam, urls] of rows) {
  total += urls.length;
  const pct = byFamSitemap.get(fam) ? ((byFamSitemap.get(fam) - urls.length) / byFamSitemap.get(fam) * 100).toFixed(1) : "0";
  console.log(`${fam}: ${urls.length} missing / ${byFamSitemap.get(fam) ?? 0} in sitemap (covered ${pct}%)`);
}
console.log("total missing:", total);
fs.writeFileSync(path.join(repoRoot, "docs", "research", "data", "coverage-missing.json"), JSON.stringify(Object.fromEntries(rows), null, 1));
